module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output done,
    output [23:0] out_bytes
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    // Internal signals
    state_t state, next_state;
    logic [23:0] out_bytes_reg, out_bytes_next;
    logic        done_reg, done_next;

    // Sequential logic (reset is active high, synchronous)
    always_ff @(posedge clk) begin
        if (reset) begin
            state    <= IDLE;
            out_bytes_reg <= 24'b0;
            done_reg   <= 1'b0;
        end else begin
            state    <= next_state;
            out_bytes_reg <= out_bytes_next;
            done_reg   <= done_next;
        end
    end

    // Combinational logic for next-state and output generation
    always_comb begin
        // Default assignments (pipeline through)
        next_state    = state;
        out_bytes_next = out_bytes_reg;
        done_next     = 1'b0;

        case (state)
            IDLE: begin
                // Discard bytes until in[3] is 1
                if (in[3]) begin
                    next_state = BYTE1;
                    out_bytes_next = 24'b0;
                    done_next     = 1'b0;
                end else begin
                    next_state = IDLE;
                    out_bytes_next = out_bytes_reg;
                    done_next     = 1'b0;
                end
            end

            BYTE1: begin
                // Capture first byte (in is byte 1)
                out_bytes_next = {in, out_bytes_reg[23:8]};
                if (in[3]) begin  // expecting byte 2 next
                    next_state = BYTE2;
                    done_next  = 1'b0;
                end else begin
                    // If in[3] is not 1, treat this as a new start
                    // (Re-assume current byte is byte 1)
                    next_state = BYTE1;
                    done_next  = 1'b0;
                end
            end

            BYTE2: begin
                // Shift in second byte
                out_bytes_next = {out_bytes_reg[23:8], in};
                if (in[3]) begin  // expecting byte 3 next
                    next_state = BYTE3;
                    done_next  = 1'b0;
                end else begin
                    // New message start
                    next_state = IDLE;
                    // Re-process current byte as byte 1
                    if (in[3]) begin
                        next_state = BYTE1;
                        out_bytes_next = {in, 16'b0};
                        done_next = 1'b0;
                    end else begin
                        next_state = IDLE;
                        done_next = 1'b0;
                    end
                end
            end

            BYTE3: begin
                // Shift in third byte
                out_bytes_next = {out_bytes_reg[23:8], in};
                // Message complete: assert done in the next cycle
                done_next = 1'b1;
                // Return to IDLE for the next message
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output assignments
    assign done     = done_reg;
    assign out_bytes = out_bytes_reg;

endmodule

