        // z is low when:
        // - x is 1 and y is 0 -> matches 25ns, 30ns, 90ns
        // - x is 0 and y is 1 -> matches 35ns, 40ns, 60ns, 75ns, 80ns, 85ns

        // Wait, at 25ns: x=1, y=0, z=0. (x & !y)
        // At 35ns: x=0, y=1, z=0. (!x & y)
        // At 45ns: x=1, y=1, z=1. (x & y)
        // At 55ns: x=0, y=0, z=1. (!x & !y)
