module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states are required to detect the sequence 1101
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00, // Waiting for the first '1'
        S_1      = 2'b01, // Matched the first '1'
        S_11     = 2'b10, // Matched '11'
        S_110    = 2'b11  // Matched '110'
    } state_t;

    state_t   state, next_state;
    logic     found; // Internal flag to latch the detection event

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
            found <= 1'b0;
        end else begin
            state <= next_state;
            if (found == 1'b0) // Only update found once
                found <= (state == S_110 && data == 1'b1) ? 1'b1 : found;
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S_IDLE:     next_state = (data == 1'b1) ? S_1     : S_IDLE;
            S_1:        next_state = (data == 1'b1) ? S_11     : S_IDLE;
            S_11:       next_state = (data == 1'b0) ? S_110    : S_11;
            S_110:      next_state = (data == 1'b1) ? S_IDLE   : S_IDLE; // Sequence 1101 detected here
            default:    next_state = S_IDLE;
        endcase
    end

    // Output logic
    // start_shifting is 1 forever after the sequence is found, until reset
    assign start_shifting = (found == 1'b1) ? 1'b1 : 1'b0;

endmodule

