    always_comb begin
        case (state)
            A: next_state = in ? B : A;
            B: next_state = in ? B : B;
            C: next_state = in ? D : A;
            D: next_state = in ? B : C;
            default: next_state = A;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always_comb begin
        case (state)
            D: out <= 1'b1;
            default: out <= 1'b0;
        endcase
    end

    // State flip-flops (sequential, positive edge-triggered)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

