module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

// State encoding
typedef enum logic [3:0] {
    WALK_LEFT   = 4'd0,
    WALK_RIGHT  = 4'd1,
    FALLING     = 4'd2,
    DIGGING     = 4'd3,
    SPLATTERED  = 4'd4
} state_t;

// State registers
state_t state, next_state;
logic [4:0] fall_counter;
logic [4:0] dig_counter;

// Direction memory register: 1 = walking right, 0 = walking left
logic walk_dir_mem;

// Next-state signals (declared to fix binding errors)
logic next_walk_dir_mem;
logic [4:0] next_fall_counter;
logic [4:0] next_dig_counter;

// Outputs (Moore machine: outputs are pure state bits)
assign walk_left   = (state == WALK_LEFT);
assign walk_right  = (state == WALK_RIGHT);
assign aaah        = (state == FALLING);
assign digging     = (state == DIGGING);

// ============================================================
// Reset Logic (positive edge triggered, asynchronous)
// ============================================================
always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        state           <= WALK_LEFT;
        walk_dir_mem    <= 1'b0; // Initialize memory to left
        fall_counter    <= 5'd0;
        dig_counter     <= 5'd0;
    end else begin
        state           <= next_state;
        walk_dir_mem    <= next_walk_dir_mem;
        fall_counter    <= next_fall_counter;
        dig_counter     <= next_dig_counter;
    end
end

// ============================================================
// Next-State / Counter Logic (combinational always block)
// ============================================================
always_comb begin
    // Default assignments: maintain current state/values unless transition
    next_state        = state;
    next_walk_dir_mem = walk_dir_mem;
    next_fall_counter = fall_counter;
    next_dig_counter  = dig_counter;

    // --- Priority 1: Fall (Highest) ---
    if (ground == 1'b0) begin
        // Lemming is in air (or just fell)
        if (state == FALLING) begin
            // Increment fall counter, max 31 (covers >20)
            if (fall_counter < 5'd31)
                next_fall_counter = fall_counter + 1'd1;
            // State stays FALLING
        end else begin
            // Transitioned into fall (from WALK or DIG)
            next_state       = FALLING;
            next_fall_counter = 5'd1; // Start counting from cycle 1 of fall
            // Preserve walking direction memory
            // If we were walking, mem holds that direction;
            // if we were digging, mem keeps the direction before dig started.
        end
    end else begin
        // ground == 1
        if (state == SPLATTERED) begin
            // Already splattered, stay splattered forever
            // counters don't matter but keep them stable
        end else if (fall_counter > 5'd20) begin
            // Fell for >20 cycles and now hit ground -> SPLATTER
            next_state = SPLATTERED;
            next_fall_counter = 5'd0;
        end else begin
            // Ground reappeared within 20 cycles -> Resume walking
            // Direction: use memory if available, else default left
            next_state = (walk_dir_mem == 1'b1) ? WALK_RIGHT : WALK_LEFT;
        end
    end

    // --- Priority 2: Dig ---
    // Can only dig if on ground, not falling, not splattered
    if (ground == 1'b1 && state != FALLING && state != SPLATTERED) begin
        if (dig == 1'b1) begin
            next_state       = DIGGING;
            next_dig_counter = dig_counter + 1'd1;
            // Memory keeps current direction (no change)
        end
    end else if (state == DIGGING && ground == 1'b0) begin
        // Started digging on ground, ground disappeared -> fall
        next_state       = FALLING;
        next_fall_counter = 5'd1;
        // dig_counter resets/increments as per fall logic handled above
    end

    // --- Priority 3: Switch Directions (Lowest) ---
    // Only if on ground, not falling, not splattered, not digging
    if (ground == 1'b1 && state != FALLING && state != SPLATTERED && state != DIGGING) begin
        if (bump_left == 1'b1 || bump_right == 1'b1) begin
            // Toggle direction and update memory to the NEW state
            if (state == WALK_LEFT) begin
                next_state = WALK_RIGHT;
                next_walk_dir_mem <= 1'b1; // Memorize new direction (Right)
            end else begin // WALK_RIGHT
                next_state = WALK_LEFT;
                next_walk_dir_mem <= 1'b0; // Memorize new direction (Left)
            end
        end
    end
end

// ============================================================
// Output Assignment (implicit via assign statements above)
// ============================================================
// walk_left/walk_right/aaah/digging driven by state assignments at top.

endmodule

