    input clk,
    input reset,
    input [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    wire [2:0] s_prime;
    wire [2:0] s_next;
    reg [2:0] s_reg;
    reg [1:0] state; // 00: low, 01: mid-low, 10: mid-high, 11: high
    reg [2:0] flow;  // {fr2, fr1, fr0, dfr}

    // Next state logic based on current sensors
    assign s_next = s;

    // State transition: detect changes
    always @(*) begin
        if (s_reg == 3'b000) begin
            // If currently low, stay low unless sensors change
            if (s != 3'b000) state <= 2'b01; // transition detected
            else state <= 2'b00;
        end else if (s_reg == 3'b111) begin
            if (s == 3'b000) state <= 2'b11; // transition detected
            else state <= 2'b111; // keep high state representation
        end else begin
            // General transition logic
            if (s == 3'b000) state <= 2'b00;
            else if (s == 3'b111) state <= 2'b11;
            else if (s == 3'b110) state <= 2'b10;
            else if (s == 3'b101) state <= 2'b10;
            else if (s == 3'b011) state <= 2'b01;
            else state <= state;
        end
    end

    // Output logic
    always @(*) begin
        case (state)
            2'b00: flow = 3'b111; // Low: all outputs
            2'b01: flow = 3'b110; // Mid-low: fr2=0, fr1=1, fr0=1, dfr=1 (implied)
            2'b10: flow = 3'b101; // Mid-high: fr2=1, fr1=0, fr0=1, dfr=1
            2'b11: flow = 3'b000; // High: all off (but reset overrides)
            default: flow = 3'b111;
        endcase
    end

    // Register update with synchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            s_reg <= 3'b000;
            state <= 2'b00;
            flow <= 3'b111;
        end else begin
            s_reg <= s_next;
            state <= (s == 3'b000) ? 2'b00 : 
                     (s == 3'b111) ? 2'b11 : state;
            flow <= (s == 3'b000) ? 3'b111 :
                    (s == 3'b111) ? 3'b000 :
                    (state == 2'b01) ? 3'b110 :
                    (state == 2'b10) ? 3'b101 : flow;
        end
    end

    // Assign outputs
    assign fr2 = flow[2];
    assign fr1 = flow[1];
    assign fr0 = flow[0];
    assign dfr = flow[3]; // Supplemental flow valve

endmodule

